    showControls: false,
  },
};

/**
 * A full image gallery. Behavioural fix (confirmed against the Jira AC and live Figma Default/
 * Hover instances): this isolated Media-only story has no wrapping `ZimmProductCard` organism to
 * hover, and the desktop prev/next arrows' hover/focus-within reveal now lives entirely on that
 * organism's own root recipe (`zimmProductCard.css.ts` docblock point 6) — so on a hover-capable/
 * desktop browser this story renders the arrows into the DOM, but they are never visible here.
 * See `Commerce/ZimmProductCard`'s own stories for the actual reveal-on-hover demonstration. The
 * touch slide indicator is unaffected by this fix — it still renders and is visible on any
 * non-hover-capable pointer; native scroll-snap paging works on every pointer type regardless.
 *
 * Unlike this file's other mobile-specific behaviours (bag/price mobile swaps, gated by a real
 * `min-width` viewport query), this split is gated by *pointer capability*
 * (`(hover: hover) and (pointer: fine)`), not viewport width — resizing the browser window alone
 * does nothing here, since a narrow desktop window is still `hover:hover`/`pointer:fine` (you're
 * still using a mouse). This project's Storybook has no viewport/touch-emulation addon installed
 * (`.storybook/main.js`'s `addons` list), so the only way to actually see the indicator in
 * Storybook is real browser DevTools device-emulation/touch-simulation mode (or a genuine touch
 * device) — not a plain resize.
 *
 * Known, accepted consequence of choosing pointer capability over viewport width (not a bug):
 * a tablet with an attached trackpad or mouse — e.g. an iPad with a Magic Keyboard — cannot be
 * guaranteed to show the indicator. iPadOS deliberately reports `hover: hover` / `pointer: fine`
 * as true once a trackpad is the active input, specifically so mouse-oriented sites behave
 * naturally with a trackpad cursor — this query cannot distinguish that from a real desktop, so
 * such a device gets the arrows instead. Confirmed and accepted (2026-09-05); revisit only if
 * this is ever reported as a real user-facing complaint.
 */
export const MultipleImages: Story = {
  args: {
    primaryImage: PRIMARY_IMAGE,
    images: GALLERY_IMAGES,
    swapOnHover: false,
    showControls: true,
  },
  // No `play`: even setting aside pointer-capability (there is no Storybook API to force a real
  // `:hover` interaction regardless), the arrows this story renders can never become visible from
  // here at all — their only reveal rule lives on ZimmProductCard's own organism root recipe
  // (`&:hover`/`&:focus-within` scoped to that root), which does not exist in this standalone
  // story's rendered tree. A play function here would prove nothing about this component. The
  // click → scrollTo("plausible shape") contract is proven deterministically in index.test.tsx
  // instead, where the mock DOM node is controlled directly.
};

