7	import React, { useEffect } from 'react';
8	import { useIntl } from 'react-intl';
9	import { useLocation } from 'react-router-dom';
10	
11	// Components
12	import { Box, Stack, Link, Text, Spinner } from '@salesforce/retail-react-app/app/components/shared/ui';
13	
14	// Project Components
15	import Seo from '@salesforce/retail-react-app/app/components/seo';
16	import Section from '@salesforce/retail-react-app/app/components/section';
17	import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';
18	
19	// Hooks
20	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
21	import { useContentfulEntries, useContentfulEntry } from '../../hooks/useContentful';
22	import { useContentfulLiveUpdates } from '@contentful/live-preview/react';
23	
24	// Constants
25	import {
26	  HOME_SHOP_PRODUCTS_CATEGORY_ID,
27	  HOME_SHOP_PRODUCTS_LIMIT,
28	  MAX_CACHE_AGE,
29	  STALE_WHILE_REVALIDATE,
30	} from '../../constants';
31	
32	import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
33	import { useProductSearch } from '@salesforce/commerce-sdk-react';
34	
35	// Types
36	import type { HomepageEntry, AnyContentfulEntry } from '../../types/contentful';
37	
38	// --- Shared layout ---
39	
40	const HomepageContent = () => {
41	  const intl = useIntl();
42	
43	  const { data: productSearchResult, isLoading: productsLoading } = useProductSearch({
44	    parameters: {
45	      refine: [`cgid=${HOME_SHOP_PRODUCTS_CATEGORY_ID as string}`, 'htype=master'] as unknown as string, // SDK types refine as string but runtime accepts string[]
46	      expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
47	      perPricebook: true,
48	      allVariationProperties: true,
49	      limit: HOME_SHOP_PRODUCTS_LIMIT,
50	    },
51	  });
52	
53	  return (
54	    <>
55	      {productSearchResult && (
56	        // From PWA template - Example on how to show products
57	        <Section
58	          padding={4}
59	          paddingTop={16}
60	          title={intl.formatMessage({
61	            defaultMessage: 'Shop Products',
62	            id: 'home.heading.shop_products',
63	          })}
64	          subtitle={intl.formatMessage(
65	            {
66	              defaultMessage: 'This section contains content from the catalog. {docLink} on how to replace it.',
67	              id: 'home.description.shop_products',
68	              description:
69	                '{docLink} is a html button that links the user to https://sfdc.co/business-manager-manage-catalogs',
70	            },
71	            {
72	              docLink: (
73	                <Link
74	                  target="_blank"
75	                  href={'https://sfdc.co/business-manager-manage-catalogs'}
76	                  textDecoration={'none'}
77	                  position={'relative'}
78	                  _after={{
79	                    position: 'absolute',
80	                    content: `""`,
81	                    height: '2px',
82	                    bottom: '-2px',
83	                    margin: '0 auto',
84	                    left: 0,
85	                    right: 0,
86	                    background: 'gray.700',
87	                  }}
88	                  _hover={{ textDecoration: 'none' }}
89	                >
90	                  {intl.formatMessage({
91	                    defaultMessage: 'Read docs',
92	                    id: 'home.link.read_docs',
93	                  })}
94	                </Link>
95	              ),
96	            },
97	          )}
98	        >
99	          <Stack pt={8} spacing={16}>
100	            <ProductScroller products={productSearchResult?.hits} isLoading={productsLoading} />
101	          </Stack>
102	        </Section>
103	      )}
104	    </>
105	  );
106	};
107	
108	// --- Normal (published) home ---
109	
110	const HomeNormal = () => {
111	  const einstein = useEinstein();
112	  const { pathname } = useLocation();
113	
114	  const { res } = useServerContext();
115	  if (res) {
116	    res.set(
117	      'Cache-Control',
118	      `s-maxage=${MAX_CACHE_AGE as number}, stale-while-revalidate=${STALE_WHILE_REVALIDATE as number}`,
119	    );
120	  }
121	
122	  const { data: contentfulData, isLoading: contentfulLoading } = useContentfulEntries<HomepageEntry>('homepage');
123	  const homepageContent = useContentfulLiveUpdates(contentfulData?.[0] ?? null);
124	
125	  useEffect(() => {
126	    einstein.sendViewPage(pathname);
127	  }, []);
128	
129	  if (contentfulLoading) {
130	    return (
131	      <Box display="flex" justifyContent="center" py={16}>
132	        <Spinner size="xl" />
133	      </Box>
134	    );
135	  }
136	
137	  if (!homepageContent) return null;
138	
139	  return <HomepageContent />;
140	};
141	
142	// --- Preview (draft) home ---
143	
144	type HomePreviewContentProps = {
145	  entryId: string;
146	};
147	
148	const HomePreviewContent = ({ entryId }: HomePreviewContentProps) => {
149	  const { data, isLoading, error } = useContentfulEntry<AnyContentfulEntry>(entryId, true);
150	  const liveData = useContentfulLiveUpdates(data);
151	
152	  if (isLoading) {
153	    return (
154	      <Box display="flex" justifyContent="center" py={16}>
155	        <Spinner size="xl" />
156	      </Box>
157	    );
158	  }
159	
160	  if (error) {
161	    return (
162	      <Box p={8}>
163	        <Text color="red.500">Error loading preview: {error.message}</Text>
164	      </Box>
165	    );
166	  }
167	
168	  if (!liveData) return null;
169	
170	  const contentTypeId = liveData.sys?.contentType?.sys?.id;
171	
172	  if (contentTypeId !== 'homepage') {
173	    return (
174	      <Box p={8}>
175	        <Text>Preview for content type &ldquo;{contentTypeId}&rdquo; is not yet configured.</Text>
176	      </Box>
177	    );
178	  }
179	
180	  return <HomepageContent />;
181	};
182	
183	// --- Page ---
184	
185	const Home = () => {
186	  const { search } = useLocation();
187	  const entryId = new URLSearchParams(search).get('entry');
188	
189	  return (
190	    <Box data-testid="home-page">
191	      <Seo
192	        title="Home Page"
193	        description="Commerce Cloud Retail React App"
194	        keywords="Commerce Cloud, Retail React App, React Storefront"
195	      />
196	      {entryId ? <HomePreviewContent entryId={entryId} /> : <HomeNormal />}
197	    </Box>
198	  );
199	};
200	
201	Home.getTemplateName = () => 'home';
202	
203	export default Home;
