{/* `Section`'s own Container/maxW wraps only its title/subtitle/actions slot, not
    `children` (node_modules/@salesforce/retail-react-app/app/components/section/index.jsx)
    -- so this grid rendered at full, unconstrained page width with no cap, stretching each
    card (and the fixed 96px/64px gap below, sourced from Figma node 3332:35665) far past
    the reference's 288px cards. Capping at 1440px reproduces it exactly: 4*288 + 3*96 =
    1440, so at `lg` each column resolves to exactly 288px; below that width the cap is a
    no-op since the viewport itself is already narrower. */}
<Box maxWidth="1440px" marginX="auto">
  <SimpleGrid
    pt={8}
    columns={{ base: 2, md: 3, lg: 4 }}
    spacingX={{ base: 6, md: 8, lg: 24 }}
    spacingY={{ base: 6, md: 8, lg: 16 }}
