export const ZimmProductCardMedia = {
  parts: [
    'root',
    'scrollContainer',
    'slide',
    'image',
    'hoverSwapBase',
    'hoverSwapOverlay',
    'badge',
    'badgeLabel',
    'close',
    'carousel',
    'arrowButton',
    'indicatorWrapper',
  ],

